import sys
input = sys.stdin.read

def compute_solution(n, mod):
    dp = [[0] * (n * n + 5) for _ in range(n)]
    dp[0][0] = 1
    for i in range(1, n):
        for j in range(len(dp[0])):
            for cnt in range(i + 1):
                if j - cnt >= 0:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - cnt]) % mod
                    if dp[i][j] == 0:
                        dp[i][j] += mod

    sums = [[0] * len(dp[0]) for _ in range(n)]
    for i in range(n):
        total = 0
        for j in range(len(dp[0])):
            total += dp[i][j]
            total %= mod
            if total == 0:
                total += mod
            sums[i][j] = total

    fact = [1] * (501 * 501)
    for i in range(1, len(fact)):
        fact[i] = (fact[i - 1] * i) % mod

    ncr = [[0] * 501 for _ in range(501)]
    ncr[0][0] = 1
    for i in range(1, 501):
        ncr[i][0] = 1
        for j in range(1, 501):
            ncr[i][j] = (ncr[i - 1][j] + ncr[i - 1][j - 1]) % mod
            if ncr[i][j] == 0:
                ncr[i][j] += mod

    result = 0
    for i in range(n - 2, -1, -1):
        cnt = n - i
        pre = n - cnt
        comb = (ncr[n][pre] * fact[pre]) % mod
        if comb == 0:
            comb += mod
        total_sum = 0

        for dif in range(1, cnt):
            for inv in range(dif, len(dp[0])):
                if dp[cnt - 2][inv] == 0:
                    break
                if inv - dif - 1 < 0:
                    continue
                x = dp[cnt - 2][inv]
                y = sums[cnt - 2][inv - dif - 1]
                x = (x * y) % mod
                if x == 0:
                    x += mod
                total_sum += (x * (cnt - dif)) % mod
                total_sum %= mod
        result += total_sum * comb
        result %= mod
        if result == 0:
            result += mod

    print(result % mod)

def main():
    data = input().split()
    T = 1
    index = 0
    for _ in range(T):
        n = int(data[index])
        index += 1
        mod = int(data[index])
        index += 1
        compute_solution(n, mod)

if __name__ == "__main__":
    main()

